/* @ts-nocheck */
import React, { useRef, useEffect, useState } from 'react';
import { cls } from '../../shared/cls.js';
import { SegmentedClasses } from '../../shared/classes/SegmentedClasses.js';
import { useDarkClasses } from '../shared/use-dark-classes.js';
import { useThemeClasses } from '../shared/use-theme-classes.js';
import { SegmentedColors } from '../../shared/colors/SegmentedColors.js';
import { getThemeSpecificProps } from '../shared/get-theme-specific-props.js';
import { useTheme } from '../shared/use-theme.js';
import { SegmentedContext } from './SegmentedContext.tsx';
import { useNavbarContext } from './NavbarContext.tsx';
import Glass from './Glass.tsx';

const Segmented = (props) => {
  const {
    component = 'div',
    className,
    colors: colorsProp,
    ios,
    material,

    // Style props
    raised,
    raisedIos,
    raisedMaterial,
    outline,
    outlineIos,
    outlineMaterial,
    strong,
    strongIos,
    strongMaterial,
    rounded,
    roundedIos,
    roundedMaterial,

    // Children
    children,

    ref,

    // Rest
    ...rest
  } = props;

  const elRef = useRef(null);
  const highlightElRef = useRef(null);
  const outlineInnerElRef = useRef(null);

  const [highlightStyle, setHighlightStyle] = useState({
    transform: '',
    width: '',
  });

  const attrs = {
    ...rest,
  };
  const theme = useTheme({ ios, material });
  const themeClasses = useThemeClasses({ ios, material });
  const dark = useDarkClasses();

  const colors = SegmentedColors(colorsProp, dark);

  const themeProps = getThemeSpecificProps(
    theme,
    {
      outline,
      rounded,
      strong,
      raised,
    },
    props
  );
  const { navbar } = useNavbarContext();

  const c = themeClasses(
    SegmentedClasses({ ...props, ...themeProps, navbar }, colors, dark)
  );

  const Component = theme === 'ios' && navbar ? Glass : component;

  const classes = cls(
    // base
    themeProps.rounded ? c.base.rounded : c.base.square,
    themeProps.raised && c.raised,
    themeProps.outline && c.outline,
    themeProps.strong && c.strong,

    className
  );

  useEffect(() => {
    if (themeProps.strong && highlightElRef.current) {
      const buttonsEl = themeProps.outline
        ? outlineInnerElRef.current
        : highlightElRef.current.parentElement;
      if (!buttonsEl) return;
      const buttons = [...buttonsEl.children].filter(
        (child) => child.tagName === 'BUTTON' || child.tagName === 'A'
      );
      const buttonsLength = buttons.length;
      const activeIndex = buttons.indexOf(
        buttonsEl.querySelector('.k-segmented-strong-button-active')
      );

      const between = '4px';
      const padding = theme === 'ios' && navbar ? '4px' : '2px';

      setHighlightStyle({
        ...highlightStyle,
        width: `calc((100% - ${padding} * 2 - ${between} * (${buttonsLength} - 1)) / ${buttonsLength})`,
        transform: `translateX(calc((${activeIndex} * 100% + ${activeIndex} * ${between}) * var(--k-rtl-reverse)))`,
      });
    }
  }, [children]);

  return (
    <Component
      ref={(el) => {
        elRef.current = el;
        if (ref && typeof ref === 'function') ref(el);
        else if (ref) ref.current = el;
      }}
      className={classes}
      {...attrs}
    >
      <SegmentedContext.Provider
        value={{
          strong: themeProps.strong,
          outline: themeProps.outline,
          rounded: themeProps.rounded,
          raised: themeProps.raised,
        }}
      >
        {themeProps.outline ? (
          <span ref={outlineInnerElRef} className={c.outlineInner}>
            {children}
          </span>
        ) : (
          children
        )}
        {themeProps.strong && (
          <span
            ref={highlightElRef}
            className={c.strongHighlight}
            style={highlightStyle}
          />
        )}
      </SegmentedContext.Provider>
    </Component>
  );
};

Segmented.displayName = 'Segmented';

export default Segmented;

/* @ts-nocheck */
import { createContext, useContext } from 'react';

export const SegmentedContext = createContext({
  strong: false,
  outline: false,
  rounded: false,
  raised: false,
});

export const useSegmentedContext = () => {
  return useContext(SegmentedContext);
};

/* @ts-nocheck */
import { createContext, useContext } from 'react';

export const NavbarContext = createContext({
  navbar: false,
});

export const useNavbarContext = () => useContext(NavbarContext);

/* @ts-nocheck */
import React, { useEffect, useRef, useContext } from 'react';
import { GlassClasses } from '../../shared/classes/GlassClasses.js';
import { GlassColors } from '../../shared/colors/GlassColors.js';
import { useThemeClasses } from '../shared/use-theme-classes.js';
import { useTheme } from '../shared/use-theme.js';
import { useDarkClasses } from '../shared/use-dark-classes.js';
import { useIosHighlight } from '../../shared/use-ios-highlight.js';
import { CapacitorContext } from '../shared/CapacitorContext.js';

const Glass = (props) => {
  const {
    component = 'div',
    colors: colorsProp,
    className,
    highlight = true,

    ios,
    material,

    // Children
    children,

    ref,

    // Rest
    ...rest
  } = props;

  const elRef = useRef(null);

  const Component = component;

  const attrs = {
    ...rest,
  };

  const theme = useTheme();

  const themeClasses = useThemeClasses({ ios, material });
  const dark = useDarkClasses();

  const colors = GlassColors(colorsProp, dark);

  const { touchHighlight } = useContext(CapacitorContext);

  const highlightData = useRef({});
  const { attachEvents, detachEvents } = useIosHighlight({
    getEl: () => elRef.current,
    enabled: highlight && theme === 'ios' && touchHighlight,
    data: highlightData.current,
  });

  const c = themeClasses(GlassClasses(props, colors), className);

  useEffect(() => {
    attachEvents();
    return () => detachEvents();
  });

  return (
    <Component
      ref={(el) => {
        if (ref && typeof ref === 'function') ref(el);
        else if (ref) ref.current = el;
        elRef.current = el;
      }}
      className={c.base}
      {...attrs}
    >
      {children}
    </Component>
  );
};

Glass.displayName = 'Glass';

export default Glass;
